# -*- coding: utf-8 -*-
"""Release 1.72.713 (HAD-712, HAD-792 package 2 follow-up: illustration line on phones (+ package 3 project row inside the buttons block)). Generated by make_deploy713.py (kl_release.build_release)."""
RELS = []
LIVE_MD5 = {}
PROOF = {}
HUNKS = {}
MAIN_LIST = "'home-v3', 'pro-card', 'cta-sheet', 'deal-sign', 'instruments', 'compound-tool', 'price-nudge', 'project-kit', 'city-projects', 'radius-prices', 'project-facts', 'near-finder', 'near-alerts', 'mortgage-market', 'campaign-brief', 'visit-trail', 'expert-advisor', 'designer' ) as $nadlan_mod"
MAIN_NEW = MAIN_LIST
BUY = "'drone-map', 'buying-hub', 'i18n', "


def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('kikar_713: no hunk on ' + rel)
    for a, b in HUNKS[rel]:
        if txt.count(a) != 1:
            raise SystemExit('kikar_713: FATAL anchor x%d in %s: %r' % (txt.count(a), rel, a[:60]))
        txt = txt.replace(a, b)
    print('[hunk] %s: %d hunk(s)' % (rel, len(HUNKS[rel])))
    return txt


def apply_main(txt):
    if txt.count(MAIN_LIST) != 1 or "'designer'" not in MAIN_LIST:
        raise SystemExit('kikar_713: FATAL: the live module list tail is not the one the previous release left')
    if txt.count(BUY) != 1 or txt.count("'buying-hub'") != 1:
        raise SystemExit('kikar_713: FATAL: buying-hub is not once before i18n in the live nadlan-config.php')
    print("[hunk] nadlan-config.php: no module change (proven)")
    return txt
